.merdeka-surface:not(:where(.merdeka-legacy, .merdeka-legacy *)) {
  --litepicker-mobilefriendly-backdrop-color-bg: #000;
}

.merdeka-surface .litepicker-backdrop:not(:where(.merdeka-legacy, .merdeka-legacy *)) {
  display: none;
  background-color: var(--litepicker-mobilefriendly-backdrop-color-bg);
  opacity: 0.3;
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
}

.merdeka-surface .litepicker-open:not(:where(.merdeka-legacy, .merdeka-legacy *)) {
  overflow: hidden;
}

.merdeka-surface .litepicker.mobilefriendly[data-plugins*="mobilefriendly"]:not(:where(.merdeka-legacy, .merdeka-legacy *)) {
  transform: translate(-50%, -50%);
  font-size: 1.1rem;
  --litepicker-container-months-box-shadow-color: #616161;
}
.merdeka-surface .litepicker.mobilefriendly-portrait:not(:where(.merdeka-legacy, .merdeka-legacy *)) {
  --litepicker-day-width: 13.5vw;
  --litepicker-month-width: calc(var(--litepicker-day-width) * 7);
}
.merdeka-surface .litepicker.mobilefriendly-landscape:not(:where(.merdeka-legacy, .merdeka-legacy *)) {
  --litepicker-day-width: 5.5vw;
  --litepicker-month-width: calc(var(--litepicker-day-width) * 7);
}

.merdeka-surface .litepicker[data-plugins*="mobilefriendly"] .container__months:not(:where(.merdeka-legacy, .merdeka-legacy *)) {
  overflow: hidden;
}

.merdeka-surface .litepicker.mobilefriendly[data-plugins*="mobilefriendly"] .container__months .month-item-header:not(:where(.merdeka-legacy, .merdeka-legacy *)) {
  height: var(--litepicker-day-width);
}

.merdeka-surface .litepicker.mobilefriendly[data-plugins*="mobilefriendly"] .container__days > div:not(:where(.merdeka-legacy, .merdeka-legacy *)) {
  height: var(--litepicker-day-width);
  display: flex;
  align-items: center;
  justify-content: center;
}


.merdeka-surface .litepicker[data-plugins*="mobilefriendly"] .container__months .month-item:not(:where(.merdeka-legacy, .merdeka-legacy *)) {
  transform-origin: center;
}

.merdeka-surface .litepicker[data-plugins*="mobilefriendly"] .container__months .month-item.touch-target-next:not(:where(.merdeka-legacy, .merdeka-legacy *)) {
  animation-name: lp-bounce-target-next;
  animation-duration: .5s;
  animation-timing-function: ease;
}

.merdeka-surface .litepicker[data-plugins*="mobilefriendly"] .container__months .month-item.touch-target-prev:not(:where(.merdeka-legacy, .merdeka-legacy *)) {
  animation-name: lp-bounce-target-prev;
  animation-duration: .5s;
  animation-timing-function: ease;
}

@keyframes lp-bounce-target-next {
  from {
    transform: translateX(100px) scale(0.5);
  }
  to {
    transform: translateX(0px) scale(1);
  }
}

@keyframes lp-bounce-target-prev {
  from {
    transform: translateX(-100px) scale(0.5);
  }
  to {
    transform: translateX(0px) scale(1);
  }
}
